# running_max :: [1, 5, 2, 8, 3]
def running_max(xs):
    out = []
    m = None
    for x in xs:
        if m is None or x > m:
            m = x
        out.append(m)
    return out

if __name__ == '__main__':
    print(running_max([1, 5, 2, 8, 3]))

